import json, subprocess

base = '649aa132711e85bcca3b38cd3752e6f5f05b0543'
tip = '1fc7b6ed35a4d2c7ac0d0ddbf985e1509d718955'
files = ['agent/chains/build-audit.chain.json','agent/chains/dual-builder-implement.chain.json',
         'agent/chains/pre-run-gate.chain.json','agent/chains/trio-implement.chain.json']
for f in files:
    old = json.loads(subprocess.check_output(['git','show',f'{base}:{f}']))
    new = json.loads(subprocess.check_output(['git','show',f'{tip}:{f}']))
    def models(o, acc):
        if isinstance(o, dict):
            for k,v in o.items():
                if k == 'model' and isinstance(v,str):
                    acc.append(v)
                else:
                    models(v, acc)
        elif isinstance(o, list):
            for i in o: models(i, acc)
    mo, mn = [], []
    models(old, mo); models(new, mn)
    # structural compare ignoring model values
    def scrub(o):
        if isinstance(o, dict):
            return {k: (scrub(v) if k!='model' else '<MODEL>') for k,v in o.items()}
        if isinstance(o, list):
            return [scrub(i) for i in o]
        return o
    same = scrub(old) == scrub(new)
    print(f"{f}: structure-identical-except-model={same} models_old={mo} models_new={mn}")
